"""Authored optional conversations; no automated duration claim."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
def b(v,e):return {'vi':v,'en':e}
rows=[
[
('Chiếc ghế gãy','The broken chair','Ngày xưa cháu ngồi đây suốt.','I used to sit here all the time.','Ừ. Con toàn kê chân lên thanh ngang. Bà mắng thì con bảo chân chưa tới đất. Giờ tới đất rồi, đừng làm như mình chưa từng cần ai đỡ nhé.','You always put your feet on the crossbar. When I scolded you, you said they could not reach the ground. They do now. Remember what needing someone felt like.'),
('Những khoản tiền','The remittances','Bà có nghĩ mẹ cháu đã sửa được chuyện cũ?','Do you think Mother put things right?','Bà chỉ mang tiền ra bưu điện. Có tháng Lan nhận, có tháng gửi lại. Mẹ con vẫn ghi cả hai vào sổ. Bà không biết người nhận cần gì mà người gửi đã gọi đó là bù đắp.','I only took the money to the post office. Some months Lan accepted it, others she returned it. Your mother recorded both. I did not know what the recipient needed, though the sender called it restitution.'),
('Bà đã im lặng','Your silence','Bà có thể kể chuyện này sớm hơn.','You could have told me sooner.','Có thể. Bà sợ con về rồi chẳng còn muốn gọi nơi này là nhà. Hóa ra bà đang giữ một chữ nhà cho mình. Nếu con ghi lời bà, ghi cả câu đó.','I could. I feared you would stop calling this place home. Perhaps I was keeping that word for myself. If you quote me, include that.')],
[
('Chậu cây vỡ','The broken plant pot','Cô còn nhớ ai làm vỡ chậu?','Do you remember who broke the pot?','Hai đứa cùng khiêng. An nhận lỗi trước vì Lan sắp có bài kiểm tra. Cô nhớ vì hôm đó cô khen con biết bảo vệ bạn. Sau này cô lại không làm được điều mình đã khen.','You carried it together. You took the blame because Lan had an exam. I praised you for protecting your friend. Later I failed to do the very thing I had praised.'),
('Chữ ký','The signature','Sao cô không từ chối ký?','Why did you not refuse to sign?','Thầy Vinh nói chỉ đổi cách ghi, trẻ con vẫn được đi học nơi khác. Cô biết một câu như vậy không trả lời chuyện gia đình các em sẽ sống ở đâu. Nhưng cô đã dùng nó để khỏi hỏi tiếp.','Vinh said it was only a change of wording, that the children could study elsewhere. I knew that did not answer where they would live. I used it to stop asking.'),
('Lời khai hôm nay','A statement today','Cô muốn sửa dòng nào trước?','Which line would you correct first?','Dòng nói Lan tự ý bỏ học. Không phải vì đó là lỗi duy nhất, mà vì cô là người có trách nhiệm với dòng ấy. Cô sẽ ký tên thật, không ký thay ai nữa.','The line saying Lan left voluntarily. Not because it was the only wrong, but because I was responsible for that line. I will sign my own name, not on anyone else’s behalf.')],
[
('Sau chuyến đò','After the crossing','Sao chú không kể chuyện cứu người?','Why did you not tell people about the rescue?','Chú có kể. Hai lần. Lần thứ ba người ta bảo chú muốn được khen. Chú thôi. Im lặng cũng có nhiều kiểu: có người chọn nó, có người nói rồi mà không ai chịu nghe.','I did. Twice. The third time they said I wanted praise. I stopped. There are different silences: some choose it; some speak and nobody listens.'),
('Chiếc thuyền','The boat','Chú có sợ lúc quay lại không?','Were you afraid when you went back?','Có. Thuyền nhỏ, trời tối. Mai cầm đèn, Lan giữ áo mẹ. Không ai ở đó nghĩ mình đang làm điều anh hùng. Chúng tôi chỉ muốn tới bờ bên kia.','Yes. Small boat, dark sky. Mai held the lamp; Lan held her mother’s coat. Nobody thought we were doing something heroic. We wanted the other bank.'),
('Một lời xin lỗi','An apology','Cháu từng trách chú. Cháu xin lỗi.','I blamed you. I am sorry.','Chú nghe rồi. Con đừng bắt Lan phải nói giống chú. Mỗi người mất một thứ khác nhau, đâu thể nhận cùng một lời xin lỗi.','I hear you. Do not expect Lan to answer the same way. People lost different things; one apology cannot fit them all.')],
[
('Lợi ích chung','The common good','Ai được tính vào chữ chung?','Who counted as the common good?','Những hộ có giấy tờ, có người đứng ra nói. Tôi coi phần còn lại là vướng mắc phải giải quyết. Khi gọi một gia đình là vướng mắc, tôi không còn phải nhìn từng người trong đó.','Households with papers, with someone who could speak for them. I called the rest an obstacle to resolve. Once a family became an obstacle, I did not have to look at the people in it.'),
('Bức tường','The wall','Ông có cho rằng bức tường đáng giá hơn nhà của họ?','Was the wall worth more than their home?','Khi ấy tôi nói bức tường bảo vệ cả trường. Bây giờ nhìn con số, tôi vẫn biết tường cần xây. Nhưng cần xây không trao cho tôi quyền lấy phần tiền đã duyệt của người khác.','I said it protected the school. Looking at the figure now, I still know it was needed. Need did not give me the right to take money already allocated to someone else.'),
('Đứng tên','Putting your name to it','Ông sẽ xác nhận điều gì bằng văn bản?','What will you confirm in writing?','Rằng tôi phê duyệt chuyển khoản đó. Tôi không thể ký thay lời kể của Mai. Và tôi không thể viết rằng tôi đã được tha thứ chỉ vì hôm nay chịu ký.','That I approved the transfer. I cannot sign on behalf of Mai’s account. Nor can I write that I am forgiven simply because I agree to sign today.')],
[
('Cuộc đời sau đó','Life afterwards','Tớ đã không biết cậu sống thế nào.','I did not know how you lived afterwards.','Có lúc rất chật vật. Cũng có hôm vui. Tớ học may, quen người thương mình, sinh Nhi. Nếu chỉ kể ngày rời xóm, người đọc sẽ tưởng cuộc đời tớ dừng ở đó. Nó không dừng.','Some times were difficult. Others were happy. I learned to sew, met someone who loved me, had Nhi. If you only tell the day we left, readers will think my life stopped there. It did not.'),
('Tiền của mẹ An','Money from your mother','Cậu có muốn tớ đưa chuyện tiền gửi vào bài không?','Do you want the remittances included?','Tớ muốn người đọc biết tiền không mua được một câu tha thứ. Nhưng đừng đưa từng tháng thiếu tiền của nhà tớ lên mặt báo. Cậu có thể nói về hành động của người gửi mà không phơi hết đời người nhận.','I want readers to know money cannot purchase forgiveness. But do not print every month my family struggled. You can describe the sender’s action without exposing the recipient’s whole life.'),
('Bản thảo cuối','The final draft','Tớ sẽ gửi cậu xem trước. Cậu có quyền bỏ lời nào là của cậu.','I will send you the draft first. You may remove words that are yours.','Vậy thì gửi. Tớ sẽ đọc, kể cả chỗ khó đọc. Cậu đừng viết kết thúc hộ tớ. Một cuộc xem xét có thể bắt đầu; đời sống còn phải tiếp tục sau dấu chấm cuối.','Then send it. I will read it, including the difficult parts. Do not write my ending for me. A review may begin; life has to continue after the final full stop.')]
]
result=[]
for i,topics in enumerate(rows):
 result.append([{'id':f'{i}-{j}','title':b(t[0],t[1]),'question':b(t[2],t[3]),'answer':b(t[4],t[5])} for j,t in enumerate(topics)])
(ROOT/'data/dialogues.json').write_text(json.dumps(result,ensure_ascii=False,indent=2),encoding='utf8')
